import {footballFormations,teamSquad,normalizeSelection,validateSelection} from './football-squads.js';
import {footballTeam} from './football-teams.js';
import {competitionModes,matchDurations,normalizeRules} from './football-rules.js';
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function buildRulesPicker(root,onChange){let value=normalizeRules(),disabled=false;
 root.innerHTML='<div class="rules-modes" aria-label="比赛规则">'+Object.entries(competitionModes).map(([id,m])=>`<button type="button" data-competition="${id}" aria-pressed="false"><b>${m.label}</b><small>${m.description}</small></button>`).join('')+'</div><div class="rules-durations" aria-label="常规时间">'+matchDurations.map(d=>`<button type="button" data-duration="${d.value}" aria-pressed="false">${d.label}<small>${d.description}</small></button>`).join('')+'</div>';
 root.addEventListener('click',e=>{const button=e.target.closest('button');if(!button||disabled)return;const next=normalizeRules({...value,...(button.dataset.competition?{mode:button.dataset.competition}:{duration:Number(button.dataset.duration)})});onChange(next);});
 return{set(next,locked=false){value=normalizeRules(next);disabled=locked;for(const button of root.querySelectorAll('button')){button.disabled=locked;button.setAttribute('aria-pressed',String(button.dataset.competition?button.dataset.competition===value.mode:Number(button.dataset.duration)===value.duration));}root.querySelector('.rules-durations').hidden=!!competitionModes[value.mode].standalone;}};
}
export const rulesSummary=rules=>{const r=normalizeRules(rules);return competitionModes[r.mode].label+(r.mode==='shootout'?' · 五轮＋突然死亡':' · '+r.duration/60+' 分钟 · 上下半场');};
let sharedEditor;
// Screen positions keep touch targets separate; field tactics use metre positions.
const formationLayout={
 '4231':[[50,91],[50,12],[34,53],[34,75],[66,75],[12,64],[88,64],[66,53],[50,33],[86,28],[14,28]],
 '433':[[50,91],[50,12],[50,58],[34,75],[66,75],[12,64],[88,64],[32,39],[68,39],[86,22],[14,22]],
 '442':[[50,91],[34,15],[34,49],[34,75],[66,75],[12,64],[88,64],[66,49],[66,15],[88,33],[12,33]],
 '352':[[50,91],[34,13],[50,74],[18,74],[82,74],[12,42],[88,42],[34,55],[66,55],[50,33],[66,13]]
};
export function getSquadEditor(){if(sharedEditor)return sharedEditor;const dialog=document.createElement('dialog');dialog.className='squad-dialog';dialog.setAttribute('aria-labelledby','squad-title');dialog.innerHTML=`<header class="squad-heading"><div><small>TEAM MANAGEMENT</small><h2 id="squad-title"></h2></div><button type="button" id="squad-close" aria-label="关闭阵容设置">×</button></header><div class="squad-content"><p id="squad-description"></p><div id="squad-formations" class="squad-formations" aria-label="阵型"></div><div class="squad-columns"><section><h3>场上阵容 <small>点击位置，再选球员</small></h3><div class="squad-pitch" id="squad-pitch" aria-label="阵容位置预览"></div></section><section><h3 id="squad-candidate-title">可用球员</h3><div id="squad-candidates" class="squad-candidates"></div></section></div></div><footer class="squad-footer"><p id="squad-message" role="status"></p><button type="button" id="squad-confirm">保存阵容</button></footer>`;document.body.append(dialog);
 const $=id=>dialog.querySelector('#'+id);let context=null,draft=null,slot=1,change=null,busy=false,saved=false;
 function render(){if(!context)return;const team=context.team||'home',opponent=context.opponent||'dortmund',squad=teamSquad(team,opponent),formation=footballFormations[draft.formation],live=!!context.live,sheet=context.sheet,field=context.players||[];
  $('squad-title').textContent=(team==='home'?'拜仁慕尼黑':footballTeam(opponent).name)+(live?' · 战术与替补':' · 首发与阵型');$('squad-description').textContent=live?`已用 ${sheet.substitutions.length} 个换人名额 · ${sheet.windows}/${context.extraTime?4:3} 次窗口。场上换人会在死球后执行；中场休息不占窗口。`:'首发 11 人，保留一名门将。点选场上位置后，可换入替补，也可交换两名首发的位置。';
  $('squad-formations').innerHTML=['4231','433','442','352'].map(id=>[id,footballFormations[id]]).map(([id,f])=>`<button type="button" data-formation="${id}" aria-pressed="${id===draft.formation}">${f.label}</button>`).join('');
  $('squad-pitch').innerHTML=draft.xi.map((number,index)=>{const member=squad.find(p=>p.player.number===number),p=field.find(p=>p.index===index&&p.team===team),[x,y]=formationLayout[draft.formation][index],dismissed=p?.dismissed;return`<button type="button" data-slot="${index}" aria-label="${formation.roles[index]} ${number} ${escape(member?.player.name)}${dismissed?' 已罚下':''}" aria-pressed="${slot===index}" ${dismissed?'disabled':''} style="left:${x}%;top:${y}%"><small>${formation.roles[index]}${p?.cautions?' ▪':''}</small><b>${number}${dismissed?' ⛔':''}</b><span>${escape(member?.player.name.split(' ').at(-1))}</span></button>`;}).join('');
  const keeper=slot===0,candidates=live?squad.filter(p=>sheet.bench.includes(p.player.number)):squad;$('squad-candidate-title').textContent=live?'替补席':'选择球员 · '+formation.roles[slot];$('squad-candidates').innerHTML=candidates.map(member=>{const n=member.player.number,unavailable=busy||!!member.keeper!==keeper||live&&(sheet.used.includes(n)||sheet.pending.some(p=>p.inNumber===n)),p=field.find(p=>p.number===n&&p.team===team);return`<button type="button" data-member="${n}" ${unavailable?'disabled':''} aria-pressed="${draft.xi[slot]===n}"><strong>${n}</strong><span><b>${escape(member.player.name)}</b><small>${member.keeper?'门将':draft.xi.includes(n)?'首发':live&&sheet.used.includes(n)?'已经替换下场':'可用替补'}${p?' · 体力 '+Math.round(p.stamina*100)+'%':''}</small></span></button>`;}).join('');
  $('squad-message').textContent=change?`本次换人：${context.selection.xi[change.slot]} ↓ ${change.inNumber} ↑`:`${formation.label} · ${live?'选择替补，或调整阵型':'点选球员完成排阵'}`;$('squad-confirm').textContent=busy?'正在保存…':live?'提交调整':'保存首发与阵型';$('squad-confirm').disabled=busy;
 }
 $('squad-formations').addEventListener('click',e=>{const button=e.target.closest('[data-formation]');if(!button||busy)return;draft.formation=button.dataset.formation;render();});
 $('squad-pitch').addEventListener('click',e=>{const button=e.target.closest('[data-slot]');if(!button||button.disabled||busy)return;slot=Number(button.dataset.slot);render();});
 $('squad-candidates').addEventListener('click',e=>{const button=e.target.closest('[data-member]');if(!button||button.disabled||busy)return;const number=Number(button.dataset.member);if(context.live){draft.xi=[...context.selection.xi];change={slot,outId:(context.team||'home')+'-'+slot,inNumber:number};draft.xi[slot]=number;}else{const previous=draft.xi.indexOf(number);if(previous>=0)draft.xi[previous]=draft.xi[slot];draft.xi[slot]=number;}render();});
 $('squad-close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{const onClose=context?.onClose;context=null;onClose?.(saved);});
 $('squad-confirm').onclick=async()=>{if(!context||busy)return;const checked=validateSelection(draft,context.team,context.opponent);if(!checked.ok){$('squad-message').textContent=checked.error;return;}busy=true;render();try{const result=await context.onSave(checked.selection,change);if(result?.ok===false)throw Error(result.error);saved=true;dialog.close();}catch(error){$('squad-message').textContent=error.message||'保存失败，请重试';}finally{busy=false;if(context){$('squad-confirm').disabled=false;$('squad-confirm').textContent=context.live?'提交调整':'保存首发与阵型';}}};
 sharedEditor={open(options){if(dialog.open)dialog.close();context={team:'home',opponent:'dortmund',...options};context.selection=normalizeSelection(context.selection,context.team,context.opponent);draft=structuredClone(context.selection);slot=1;change=null;busy=saved=false;render();dialog.showModal();},get isOpen(){return dialog.open;},close(){dialog.close();}};return sharedEditor;
}
